-- ---- 1./2./3. Aktiver Bandbestand = 141, alle v2-Zielbands vorhanden/aktiv, keine fehlt ----
active_count_row as (
  select 'band_bestand'::text as report_section, 'aktive_baender_gesamt'::text as key,
    '141'::text as expected, count(*)::text as actual, count(*) = 141 as match
  from public.bands where status = 'active'
),
band_presence_rows as (
  select 'band_bestand'::text as report_section, bt.name as key,
    'vorhanden, status=active, slug korrekt'::text as expected,
    case when b.id is null then 'NICHT GEFUNDEN'
         when b.status <> 'active' then 'status=' || b.status
         when b.slug <> bt.slug then 'abweichender slug=' || b.slug
         else 'ok' end as actual,
    (b.id is not null and b.status = 'active' and b.slug = bt.slug) as match
  from band_targets bt
  left join public.bands b on b.id = bt.id
),
no_extra_active_band_row as (
  select 'band_bestand'::text, 'keine_zusaetzliche_aktive_band'::text,
    '0'::text,
    count(*)::text,
    count(*) = 0
  from public.bands b
  where b.status = 'active' and not exists (select 1 from band_targets bt where bt.id = b.id)
),

-- ---- 4./5. 135 mit Zuordnung, 6 als Empty State ----
with_assignment_row as (
  select 'band_assignment_counts'::text, 'baender_mit_zuordnung'::text, '135'::text,
    count(*)::text, count(*) = 135
  from public.bands b
  where b.status = 'active' and exists (select 1 from public.band_repertoire_styles brs where brs.band_id = b.id)
),
empty_state_row as (
  select 'band_assignment_counts'::text, 'baender_als_empty_state'::text, '6'::text,
    count(*)::text, count(*) = 6
  from public.bands b
  where b.status = 'active' and not exists (select 1 from public.band_repertoire_styles brs where brs.band_id = b.id)
),

-- ---- 6. Alle 141 Baender exakt gegen v2 (IDs, Slugs, Style-Namen, Style-Slugs, Reihenfolge) ----
band_exact_match_rows as (
  select
    'band_exact_match'::text as report_section,
    bt.name as key,
    array_to_string(bt.chip_names, ' | ') as expected,
    coalesce((
      select array_to_string(array_agg(rs.name order by brs.sort_order), ' | ')
      from public.band_repertoire_styles brs
      join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = bt.id
    ), '') as actual,
    coalesce((
      select array_agg(rs.name order by brs.sort_order)
      from public.band_repertoire_styles brs
      join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = bt.id
    ), '{}'::text[]) = bt.chip_names as match
  from band_targets bt
),

-- ---- 7. Deep Decision ----
deep_decision_row as (
  select 'special_case'::text, 'Deep Decision'::text, 'Moderne Kirchenmusik'::text,
    coalesce((
      select array_to_string(array_agg(rs.name order by brs.sort_order), ' | ')
      from public.band_repertoire_styles brs join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = 'e03af73e-ceed-44e9-919a-02e74a1964bc'::uuid
    ), '(keine Zuordnung)'),
    exists (
      select 1 from public.band_repertoire_styles brs
      join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = 'e03af73e-ceed-44e9-919a-02e74a1964bc'::uuid and rs.name = 'Moderne Kirchenmusik'
    ) and (select count(*) from public.band_repertoire_styles where band_id = 'e03af73e-ceed-44e9-919a-02e74a1964bc'::uuid) = 1
),

-- ---- 8. Donnaweda ----
donnaweda_row as (
  select 'special_case'::text, 'Donnaweda'::text,
    'Volksmusik bis Charts | Gabalier bis Fliegerlied | Walzer bis aktuelle Hits'::text,
    coalesce((
      select array_to_string(array_agg(rs.name order by brs.sort_order), ' | ')
      from public.band_repertoire_styles brs join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = 'ba000001-0000-0000-0000-000000000001'::uuid
    ), '(keine Zuordnung)'),
    coalesce((
      select array_agg(rs.name order by brs.sort_order)
      from public.band_repertoire_styles brs join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = 'ba000001-0000-0000-0000-000000000001'::uuid
    ), '{}'::text[]) = array['Volksmusik bis Charts','Gabalier bis Fliegerlied','Walzer bis aktuelle Hits']::text[]
),

-- ---- 9. Alle 7 geschuetzten Referenzbands exakt (Teilmenge von band_exact_match_rows, hier separat ausgewiesen) ----
protected_rows as (
  select
    'protected_bestand'::text as report_section,
    bt.name as key,
    array_to_string(bt.chip_names, ' | ') as expected,
    coalesce((
      select array_to_string(array_agg(rs.name order by brs.sort_order), ' | ')
      from public.band_repertoire_styles brs join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = bt.id
    ), '') as actual,
    coalesce((
      select array_agg(rs.name order by brs.sort_order)
      from public.band_repertoire_styles brs join public.repertoire_styles rs on rs.id = brs.repertoire_style_id
      where brs.band_id = bt.id
    ), '{}'::text[]) = bt.chip_names as match
  from band_targets bt
  where bt.id in ('f9baa4fc-d396-4a52-8991-dd7d63e01baf'::uuid, '354e2447-41f0-487a-a46d-a2d209dc890b'::uuid, '098a9022-9d58-4348-8157-ba6688f2e9bf'::uuid, '82acc533-07d3-4479-82fe-31983711a3e0'::uuid, '332dfade-6e61-4f6e-b33d-23a03b610d24'::uuid, '65a12d3a-c654-46b7-b738-0feb94fc7e8a'::uuid, '5c9bdb9e-d3ad-4950-aa22-7a3aedfb61db'::uuid)
),

-- ---- 10./11. Alle 322 Zielchips vorhanden, eindeutiger Slug, aktiv, Name exakt ----
chip_presence_rows as (
  select
    'catalog_chip_presence'::text as report_section,
    ct.slug as key,
    ct.name || ' (status=active)' as expected,
    case when rs.id is null then 'NICHT GEFUNDEN'
         when rs.name <> ct.name then 'abweichender Name: ' || rs.name
         when rs.status <> 'active' then 'status=' || rs.status
         else 'ok' end as actual,
    (rs.id is not null and rs.name = ct.name and rs.status = 'active') as match
  from chip_targets ct
  left join public.repertoire_styles rs on rs.slug = ct.slug
),
chip_count_row as (
  select 'catalog_chip_presence'::text, 'gesamtzahl_zielchips'::text, '322'::text,
    (select count(*) from chip_targets)::text,
    (select count(*) from chip_targets) = 322
),
catalog_active_count_row as (
  select 'catalog_totals'::text, 'aktive_katalogzeilen_gesamt'::text, '322'::text,
    count(*)::text, count(*) = 322
  from public.repertoire_styles where status = 'active'
),

-- ---- 12. Keine Namens-/Slug-Kollisionen innerhalb der Zielmenge (im aktiven Katalog) ----
no_collision_row as (
  select 'catalog_totals'::text, 'eindeutige_aktive_slugs'::text, '322'::text,
    count(distinct slug)::text, count(distinct slug) = 322
  from public.repertoire_styles where status = 'active'
),
no_name_collision_row as (
  select 'catalog_totals'::text, 'eindeutige_aktive_namen'::text, '322'::text,
    count(distinct name)::text, count(distinct name) = 322
  from public.repertoire_styles where status = 'active'
),

-- ---- 13. Glory Times unveraendert ----
glory_times_row as (
  select 'excluded_bands'::text, 'Glory Times'::text,
    'status=draft, is_published=false, 0 Zuordnungen'::text,
    coalesce((select 'status=' || status || ', is_published=' || is_published::text from public.bands where name = 'Glory Times'), '(nicht gefunden)')
    || ', ' || (select count(*)::text from public.band_repertoire_styles brs join public.bands b on b.id=brs.band_id where b.name='Glory Times') || ' Zuordnung(en)',
    exists (select 1 from public.bands where name = 'Glory Times' and status = 'draft' and is_published is false)
    and not exists (select 1 from public.band_repertoire_styles brs join public.bands b on b.id = brs.band_id where b.name = 'Glory Times')
),

-- ---- 14./15. Die 5 ausgeschlossenen Bands weiterhin ohne Datensatz / nicht angelegt ----
excluded_absent_rows as (
  select 'excluded_bands'::text as report_section, n as key,
    'kein Datensatz in public.bands'::text as expected,
    case when exists (select 1 from public.bands where name = n) then 'ANGELEGT' else 'weiterhin abwesend' end as actual,
    not exists (select 1 from public.bands where name = n) as match
  from unnest(array['Stockerholzer Buam', 'Brugger Buam', 'Björn Bussler + Band', 'Sauschwanzlbeisser', 'Soulmaid']) as n
),

-- ---- 16. Keine aktive Zielband mit zusaetzlichen/falsch sortierten Zeilen ----
no_extra_rows_row as (
  select 'band_assignment_counts'::text, 'keine_baender_mit_ueberzaehligen_zeilen'::text, '0'::text,
    count(*)::text, count(*) = 0
  from (
    select brs.band_id, count(*) as cnt
    from public.band_repertoire_styles brs
    join band_targets bt on bt.id = brs.band_id
    group by brs.band_id, bt.chip_slugs
    having count(*) <> array_length(bt.chip_slugs, 1)
  ) x
),

-- ---- 17. RPC- und Rechte-Smoke-Check ----
fn_resolved as (
  select to_regprocedure('public.set_band_repertoire_styles(uuid, uuid[])') as fn_oid
),
rpc_exists_row as (
  select 'security_smoke'::text, 'rpc_exists'::text, 'gefunden'::text,
    case when fn_oid is null then 'NICHT GEFUNDEN' else 'gefunden' end,
    fn_oid is not null
  from fn_resolved
),
rpc_secdef_row as (
  select 'security_smoke'::text, 'rpc_security_definer'::text, 'true'::text,
    coalesce((select prosecdef::text from pg_proc where oid = fn_oid), '(nicht gefunden)'),
    coalesce((select prosecdef from pg_proc where oid = fn_oid), false)
  from fn_resolved
),
rpc_service_role_row as (
  select 'security_smoke'::text, 'rpc_execute_service_role'::text, 'true'::text,
    case when fn_oid is null then '(nicht gefunden)' else has_function_privilege('service_role', fn_oid, 'EXECUTE')::text end,
    coalesce(has_function_privilege('service_role', fn_oid, 'EXECUTE'), false)
  from fn_resolved
),
rpc_anon_blocked_row as (
  select 'security_smoke'::text, 'rpc_execute_anon_blocked'::text, 'true'::text,
    case when fn_oid is null then '(nicht gefunden)' else (not has_function_privilege('anon', fn_oid, 'EXECUTE'))::text end,
    coalesce(not has_function_privilege('anon', fn_oid, 'EXECUTE'), false)
  from fn_resolved
),
rpc_authenticated_blocked_row as (
  select 'security_smoke'::text, 'rpc_execute_authenticated_blocked'::text, 'true'::text,
    case when fn_oid is null then '(nicht gefunden)' else (not has_function_privilege('authenticated', fn_oid, 'EXECUTE'))::text end,
    coalesce(not has_function_privilege('authenticated', fn_oid, 'EXECUTE'), false)
  from fn_resolved
),
table_dml_blocked_rows as (
  select 'security_smoke'::text as report_section,
    t.table_name || ':' || p.priv as key,
    ('kein ' || p.priv || ' fuer service_role')::text as expected,
    has_table_privilege('service_role', 'public.' || t.table_name, p.priv)::text as actual,
    not has_table_privilege('service_role', 'public.' || t.table_name, p.priv) as match
  from (values ('repertoire_styles'), ('band_repertoire_styles')) t(table_name)
  cross join (values ('INSERT'), ('UPDATE'), ('DELETE'), ('TRUNCATE')) p(priv)
),
table_select_rows as (
  select 'security_smoke'::text as report_section,
    t.table_name || ':SELECT' as key,
    'true'::text as expected,
    has_table_privilege('service_role', 'public.' || t.table_name, 'SELECT')::text as actual,
    has_table_privilege('service_role', 'public.' || t.table_name, 'SELECT') as match
  from (values ('repertoire_styles'), ('band_repertoire_styles')) t(table_name)
)

select * from active_count_row
union all select * from band_presence_rows
union all select * from no_extra_active_band_row
union all select * from with_assignment_row
union all select * from empty_state_row
union all select * from band_exact_match_rows
union all select * from deep_decision_row
union all select * from donnaweda_row
union all select * from protected_rows
union all select * from chip_presence_rows
union all select * from chip_count_row
union all select * from catalog_active_count_row
union all select * from no_collision_row
union all select * from no_name_collision_row
union all select * from glory_times_row
union all select * from excluded_absent_rows
union all select * from no_extra_rows_row
union all select * from rpc_exists_row
union all select * from rpc_secdef_row
union all select * from rpc_service_role_row
union all select * from rpc_anon_blocked_row
union all select * from rpc_authenticated_blocked_row
union all select * from table_dml_blocked_rows
union all select * from table_select_rows
order by report_section, key;
